import { SimpleChanges } from '@angular/core';
import { ReplaySubject, Subscription } from 'rxjs';


/**
 * Defines a contract for filter change handlers that react to lifecycle updates.
 *
 * Implementations should perform filtering logic when changes occur, clean up resources,
 * and provide helpers for detecting specific change scenarios.
 */
export interface IFilterChanges {
    observe(changes: SimpleChanges): void;
    unObserve(): void;
    notEmpty<T>(key: string, handler: (t: T) => void): void;
    has<T>(key: string, handler: (t: T) => void): void;
    notFirst<T>(key: string, handler: (t: T) => void): void;
    notFirstAndEmpty<T>(key: string, handler: (t: T) => void): void;
}

export class UbckFilterChangeObserver implements IFilterChanges {
    private subject = new ReplaySubject<SimpleChanges>(1);
    private subscriptions: Subscription = new Subscription();

    observe(changes: SimpleChanges) {
        this.subject.next(changes);
    }

    unObserve() {
        this.subscriptions.unsubscribe();
    }

    notEmpty<T>(key: string, handler: (t: T) => void) {
        this.subscriptions.add(
            this.subject.subscribe(changes => {
                if (changes[key]) {
                    const value: T = changes[key].currentValue;
                    if (value !== undefined && value !== null) {
                        handler(value);
                    }
                }
            })
        );
    }

    has<T>(key: string, handler: (t: T) => void) {
        this.subscriptions.add(
            this.subject.subscribe(changes => {
                if (changes[key]) {
                    const value: T = changes[key].currentValue;
                    handler(value);
                }
            })
        );
    }

    notFirst<T>(key: string, handler: (t: T) => void) {
        this.subscriptions.add(
            this.subject.subscribe(changes => {
                if (changes[key] && !changes[key].isFirstChange()) {
                    const value: T = changes[key].currentValue;
                    handler(value);
                }
            })
        );
    }

    notFirstAndEmpty<T>(key: string, handler: (t: T) => void) {
        this.subscriptions.add(
            this.subject.subscribe(changes => {
                if (changes[key] && !changes[key].isFirstChange()) {
                    const value: T = changes[key].currentValue;
                    if (value !== undefined && value !== null) {
                        handler(value);
                    }
                }
            })
        );
    }
}